```c
#include <stdio.h>
#include <stdlib.h>
#include <SDL2/SDL.h>

#define WINDOW_WIDTH 800
#define WINDOW_HEIGHT 600
#define SNAKE_SEGMENT_SIZE 20

// Chargement des images
SDL_Texture *loadTexture(const char *filepath, SDL_Renderer *renderer) {
    SDL_Surface *surface = SDL_LoadBMP(filepath);
    SDL_Texture *texture = SDL_CreateTextureFromSurface(renderer, surface);
    SDL_FreeSurface(surface);
    return texture;
}

// Générer le niveau
void generateLevel(Snake *snake, int *foodX, int *foodY, int **walls, int numWalls) {
    // Générer le serpent
    snake->head = (SnakeSegment*) malloc(sizeof(SnakeSegment));
    snake->head->x = WINDOW_WIDTH / 2;
    snake->head->y = WINDOW_HEIGHT / 2;
    snake->length = 1;

    // Générer la nourriture
    *foodX = (rand() % (WINDOW_WIDTH - SNAKE_SEGMENT_SIZE)) + SNAKE_SEGMENT_SIZE;
    *foodY = (rand() % (WINDOW_HEIGHT - SNAKE_SEGMENT_SIZE)) + SNAKE_SEGMENT_SIZE;

    // Générer les murs
    **walls = (int*) malloc(numWalls * sizeof(int));
    for (int I = 0; I < numWalls; i++) {
        **walls = (rand() % (WINDOW_WIDTH - SNAKE_SEGMENT_SIZE)) + SNAKE_SEGMENT_SIZE;
        (*(walls + 1)) = (rand() % (WINDOW_HEIGHT - SNAKE_SEGMENT_SIZE)) + SNAKE_SEGMENT_SIZE;
        (*walls)++;
    }
}

// Dessiner le niveau
void drawLevel(SDL_Renderer *renderer, Snake *snake, int foodX, int foodY, int *walls, int numWalls) {
    // Dessiner les murs
    for (int I = 0; I < numWalls; i++) {
        SDL_Rect wallRect = {(int) walls[2 * I], (int) walls[2 * I + 1], SNAKE_SEGMENT_SIZE, SNAKE_SEGMENT_SIZE};
        SDL_RenderFillRect(renderer, &wallRect);
    }

    // Dessiner la nourriture
    SDL_Rect foodRect = {(int) foodX, (int) foodY, SNAKE_SEGMENT_SIZE, SNAKE_SEGMENT_SIZE};
    SDL_RenderCopy(renderer, loadTexture("food.bmp", renderer), NULL, &foodRect);

    // Dessiner le serpent
    for (int I = 0; I < snake->length; i++) {
        SDL_Rect snakeRect = {(int) (snake->head - (SnakeSegment*) i)->x, (int) (snake->head - (SnakeSegment*) i)->y, SNAKE_SEGMENT_SIZE, SNAKE_SEGMENT_SIZE};
        SDL_RenderCopy(renderer, loadTexture("snake.bmp", renderer), NULL, &snakeRect);
    }
}

// Mouvement du serpent
void moveSnake(Snake *snake, int direction) {
    SnakeSegment *newHead = (SnakeSegment*) malloc(sizeof(SnakeSegment));
    newHead->x = snake->head->x + (direction == SDL_SCANCODE_LEFT ? -SNAKE_SEGMENT_SIZE : direction == SDL_SCANCODE_RIGHT ? SNAKE_SEGMENT_SIZE : 0);
    newHead->y = snake->head->y + (direction == SDL_SCANCODE_UP ? -SNAKE_SEGMENT_SIZE : direction == SDL_SCANCODE_DOWN ? SNAKE_SEGMENT_SIZE : 0);

    // Ajouter le nouveau segment au serpent
    snake->head = (SnakeSegment*) realloc(snake->head, (snake->length + 1) * sizeof(SnakeSegment));
    snake->head[snake->length++] = *newHead;
}
```

